package com.example.starter.bonded.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.math.BigDecimal;

/**
 * 转关申请商品项（税号、数量、单价）。
 *
 * @param hsCode 商品税号
 * @param quantity 数量（件），必须为正整数
 * @param unitPrice 单价（元），必须大于 0
 */
public record ItemRequest(
        @NotBlank(message = "税号不能为空")
        String hsCode,
        @NotNull @Positive(message = "数量必须为正整数")
        Long quantity,
        @NotNull @DecimalMin(value = "0.0001", message = "单价必须大于 0")
        BigDecimal unitPrice) {
}

package com.example.starter.bonded.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

import java.util.List;

/**
 * 转关申请请求。
 *
 * @param requestId 幂等请求号
 * @param enterpriseId 申请企业编号
 * @param fromWarehouse 起运仓编号
 * @param toWarehouse 目的仓编号（不得与起运仓相同）
 * @param items 商品项明细
 */
public record ApplyTransferRequest(
        @NotBlank(message = "requestId 不能为空")
        String requestId,
        @NotBlank(message = "企业编号不能为空")
        String enterpriseId,
        @NotBlank(message = "起运仓不能为空")
        String fromWarehouse,
        @NotBlank(message = "目的仓不能为空")
        String toWarehouse,
        @NotEmpty(message = "商品项不能为空")
        @Valid
        List<ItemRequest> items) {
}

package com.example.starter.bonded.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 单批核销中的一个商品项数量。
 *
 * @param hsCode 商品税号，必须是转关单中已核注的商品项
 * @param quantity 本批到货核销数量（件），必须为正整数
 */
public record VerifyItemRequest(
        @NotBlank(message = "税号不能为空")
        String hsCode,
        @NotNull @Positive(message = "核销数量必须为正整数")
        Long quantity) {
}

